    frontier = []
    whites = H*W
    for i in range(H):
        for j in range(W):
            if table[i][j] == '#':
                frontier.append((i, j))
                whites -= 1
    count = 0
    while whites != 0:
        new_frontier = []
        for i, j in frontier:
            for i0, j0 in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
