def initialize_maze(h, w):
    grid = dict()

    for x in range(w + 2):
        grid[(x, 0)] = "#"
        grid[(x, h + 1)] = "#"

    for y in range(h + 2):
        grid[(0, y)] = "#"
        grid[(w + 1, y)] = "#"

