def main():
    def bfs():
        que = deque()
        que.append((1, 1, 0))

        while que:
            x, y, count = que.popleft()
            for mx, my in ((1, 0), (0, 1), (-1, 0), (0, -1)):
                nx, ny = x + mx, y + my
                if grid[(nx, ny)] == ".":
                    que.append((nx, ny, count + 1))
                    grid[(nx, ny)] = "!"
                elif grid[(nx, ny)] == "G":
                    min_count = count + 1
                    return min_count
        return - 1

    h, w = map(int, readline().split())
