def warsharll_floyd(c):
    n = len(c)
    for k in range(n):  # iからjへ向かう途中に中継する頂点
        for i in range(n):  # 始点
            for j in range(n):  # 終点
                # 現時点のiからjへ向かうコスト と kを経由してjに向かうコストの小さい方
                c[i][j] = min(c[i][j], c[i][k] + c[k][j])
    return c


