def dfs(v):
    stack = [v]
    dist = [None] * (n + 1)
    dist[v] = 0
    while stack:
        x = stack.pop()
        for y in graph[x]:
            if dist[y] is None:
                dist[y] = dist[x] + 1
                stack.append(y)
    return dist

