import math

def minkovski(a, b, p):
    if p == 'inf':
        tmp_arr = [abs(x-y) for x, y in zip(a, b)]
        max_val = tmp_arr[0]
        for i in range(1, len(a)):
            if max_val < tmp_arr[i]:
                max_val = tmp_arr[i]
        return max_val
    else:
        dst = 0
        for x, y in zip(a, b):
            dst += pow(abs(x-y), p)
        dst = pow(dst, 1/p)
        return dst

