class UnionFind():
    def __init__(self, n):
        self.n = n
        self.para = [-1] * (n + 1)

    def find(self, x):
        if self.para[x] < 0:
            return x
        else:
            self.para[x] = self.find(self.para[x])
            return self.para[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x > y:
            x, y = y, x
        if x == y:
            return
        else:
            self.para[x] += self.para[y]
            self.para[y] = x
    def isSame(self, x, y):
        return self.find(x) == self.find(y)

    def count(self,x):
        return -self.para[self.find(x)]
