def resolve():
    S_ = SS()
    T = SS()

    len_S = len(S_)
    len_T = len(T)

    # TはS'のなるべく右側にあるべき
    idx = -1
    for i in range(len_S - len_T, -1, -1):
        exists = True
        for j in range(len_T):
            if S_[i+j] != '?' and S_[i+j] != T[j]:
                exists = False
                break
        if exists:
            idx = i
            break

    if idx == -1:
        print('UNRESTORABLE')
    else:
        ans = list(S_)
        for i in range(len_S):
            if S_[i] == '?':
                if idx <= i < idx + len_T:
                    ans[i] = T[i-idx]
                else:
                    ans[i] = 'a'

        print(''.join(ans))

if __name__ == '__main__':
    resolve()

