class WarshallFloyd():
  def __init__(self, N):
    self.N = N
    self.d = [[float("inf") for i in range(N)] for j in range(N)]
    self.prev = [[i for j in range(N)] for i in range(N)]
    for i in range(N):
      self.prev[i][i] = i

  def add(self, u, v, c, directed=False):
    if directed is False:
      self.d[u][v] = c
      self.d[v][u] = c
    else:
      self.d[u][v] = c

  def WarshallFloyd_search(self):
    for k in range(self.N):
      for i in range(self.N):
        for j in range(self.N):
          if self.d[i][j] > self.d[i][k] + self.d[k][j]:
            self.d[i][j] = self.d[i][k] + self.d[k][j]
            if i!=j:
              self.prev[i][j] = self.prev[k][j]

    hasNegativeCycle = False
    for i in range(self.N):
      if self.d[i][i] < 0:
        hasNegativeCycle = True
        break
    for i in range(self.N):
      self.d[i][i] = 0
    return hasNegativeCycle, self.d

