    g = Graph(n)

    for i in range(n-1):
        a, b = list(map(int, readline().split()))
        g.add_edge(a, b)

    que = deque()
    que.append((1, 0, k))

    while que:
        current, parent, c = que.popleft()
        g.vertices[current].color = c
        next_c = k - 1 - parent
        for i in g.neighbors(current):
            if g.vertices[i].color == -1:
                que.append((i, 1, next_c))
                next_c -= 1

    ans = 1

    for i in range(1, n + 1):
        ans *= g.vertices[i].color
        ans %= MOD

    print(ans)


