def divisors(N: int) -> set:
    from math import sqrt

    s = {1, N}
    for i in range(2, int(sqrt(N))+1):
        if N % i == 0:
            s.add(i)
            s.add(N // i)
    return s

def check(n, k):
    if k == 1:
        return False
    while n >= k:
        if n % k == 0:
            n //= k
        else:
            n %= k
    return n == 1

