MOD = 998244353

class ModInt:
    def __init__(self, x=0):
        self.x = x % MOD

    def __str__(self):
        return str(self.x)

    __repr__ = __str__

    def __add__(self, other):
        return (
            ModInt(self.x + other.x) if isinstance(other, ModInt) else
            ModInt(self.x + other)
        )

    def __sub__(self, other):
        return (
            ModInt(self.x - other.x) if isinstance(other, ModInt) else
            ModInt(self.x - other)
        )

    def __mul__(self, other):
        return (
            ModInt(self.x * other.x) if isinstance(other, ModInt) else
            ModInt(self.x * other)
        )

    def __truediv__(self, other):
        return (
            ModInt(self.x * pow(other.x, MOD - 2)) if isinstance(other, ModInt) else
            ModInt(self.x * pow(other, MOD - 2))
        )

    def __pow__(self, other):
        return (
            ModInt(pow(self.x, other.x)) if isinstance(other, ModInt) else
            ModInt(pow(self.x, other))
        )

    __radd__ = __add__

    def __rsub__(self, other):
        return (
            ModInt(other.x - self.x) if isinstance(other, ModInt) else
            ModInt(other - self.x)
        )

    __rmul__ = __mul__

    def __rtruediv__(self, other):
        return (
            ModInt(other.x * pow(self.x, MOD - 2)) if isinstance(other, ModInt) else
            ModInt(other * pow(self.x, MOD - 2))
        )

    def __rpow__(self, other):
        return (
            ModInt(pow(other.x, self.x)) if isinstance(other, ModInt) else
            ModInt(pow(other, self.x))
        )

@mt
def slv(N, K, LR):

    memo = [ModInt(0)] * (N+2)
    memo[1] = 1
    memo[1+1] = -1
    for i in range(1, N+1):
        memo[i] += memo[i-1]
        for l, r in LR:
            ll = min(N+1, i+l)
            rr = min(N+1, i+r+1)
            memo[ll] += memo[i]
            memo[rr] -= memo[i]

    return memo[N]


