                R[i] = -min(max_h, t)
        else:
            if t > p: # new
                p = t
                if t != r:
                    return 0
            else:
                if r > t:
                    return 0

    answer = 1
    for r in R:
        if r > 0:
            answer *= 1
        else:
            max_h = -r
            answer *= max_h
            answer %= M
