def find(list_path, x):
  if list_path[x] != x:
    list_path[x] = find(list_path, list_path[x])
  return list_path[x]

def union(list_path, x, y):
  x = find(list_path, x)
  y = find(list_path, y)
  if x != y:
    list_path[x] = min(x, y)
    list_path[y] = list_path[x]

