def isOK(target,mid):
  return target < mid
def isOK_dep(target,mid):
  return target <= mid

def bin_search(l,r,li,target):
  left = l
  right = r
  while right-left>1:
    mid = (left + right)//2
    if isOK(target,li[mid]):
      right = mid
    else:
      left = mid
  return left

def bin_search_dep(l,r,li,target):
  left = l
  right = r
  while right-left>1:
    mid = (left + right)//2
    if isOK_dep(target,li[mid]):
      right = mid
    else:
      left = mid
  return left

