def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        print(e - s, 'sec', file=sys.stderr)
        return ret

    return wrap


@mt
def slv(N, A):

    if A[0] != 0:
        return -1

    for i in range(N - 1):
        if A[i + 1] - A[i] > 1:
            return -1

    ans = A[-1]
    for i in range(N - 1):
        if A[i] >= A[i + 1]:
            ans += A[i]
    return ans


