def solve(N: int, A: "List[int]"):
    def g():
        ctr = Counter(A)
        for key in sorted(ctr.keys(), reverse=True):
            for _ in range(ctr[key] // 2):
                yield key
    gg = g()
    try:
        print(next(gg) * next(gg))
    except StopIteration:
        print(0)


