def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, A):
    b = deque()
    A.sort()
    for i in range(N//2):
        if i % 2 == 0:
            b.appendleft(A[i])
            b.append(A[N-i-1])
        else:
            b.append(A[i])
            b.appendleft(A[N-i-1])
    if N % 2 !=  0:
        a = A[N//2]
        l = b[0]
        r = b[-1]
        if abs(a-l) > abs(a-r):
            b.appendleft(a)
        else:
            b.append(a)

    ans = 0
    for i in range(N-1):
        ans += abs(b[i]-b[i+1])

    return ans


