def insertion(a, n, g, cnt):
    for i in range(g, n):
        v = a[i]
        j  = i - g
        while v < a[j] and j >= 0:
            a[j+g] = a[j]
            j -= g
            cnt += 1
        else:
            a[j+g] = v
    else:
        return cnt

