    s = int(a)
    e = int(b)+1

    print(text[s:e])

def reverse_text(text, a, b):
    s = int(a)
    e = int(b)+1

    return text[:s] + text[s:e][::-1] + text[e:]

def replace_text(text, a, b, p):
    s = int(a)
    e = int(b)+1

    return text[0:s] + p + text[e:]

