    ans = modpow(2, N) - 1
    c = 1
    for i in range(1, A + 1):
        c *= N - i + 1
        c %= MOD
        c *= modinv(i) % MOD
    ans -= c
    c = 1
    for i in range(1, B + 1):
        c *= N - i + 1
        c %= MOD
        c *= modinv(i) % MOD
    ans -= c
    ans += MOD
    ans %= MOD
    print(ans)


