class UnionFind():
    def __init__(self, N):
        self.par = [-1]*(N)
        self.size = [1]*(N)

    def find(self, x):
        if self.par[x] == -1:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        px = self.find(x)
        py = self.find(y)
        if px != py:
            if self.size[px] < self.size[py]:
                px, py = py, px
            self.size[px] += self.size[py]
            self.par[py] = px

