        nonlocal answer
        bc = BC.pop()
        bc[0] -= 1
        if bc[0] > 0:
            BC.append(bc)
        return bc[1]

    while chosen < N:
        if A and BC:
            if A[-1] > BC[-1][1]:
                answer += A.pop()
            else:
                answer += pop_bc()
        elif A:
            answer += A.pop()
        else:
            answer += pop_bc()
        chosen += 1
    return answer


