def rec(x):
    if memo[x] >= 0:
        return memo[x]
    multi = 0
    # x * 2, x * 3...について
    for i in range(x * 2, K + 1, x):
        multi += rec(i)
    memo[x] = pow(K // x, N, mod) - multi
    res = memo[x]
    return res

