def find(parent, v):
    if v == parent[v]:
        return v
    parent[v] = find(parent, parent[v])
    return parent[v]

def unite(parent, rank, u, v):
    u = find(parent, u)
    v = find(parent, v)
    if u == v:
        return
    if rank[u] < rank[v]:
        parent[u] = v
    else:
        parent[v] = u
        if rank[u] == rank[v]:
            rank[u] += 1

