def culc(array,k,count):
    array=array.T
    cuts=np.zeros(array.shape[1])
    for i in range(array.shape[0]):
        if any(array[i]>k):
            return 10**6
        elif any(array[i]+cuts>k):
            cuts=array[i]
            count+=1
        else:
            cuts+=array[i]
    return count


