def root(x):
    if par[x] == x:
        return x
    par[x] = root(par[x])
    return par[x]

def same(x, y):
    rx = root(x)
    ry = root(y)
    return rx == ry

def unite(x, y):
    x = root(x)
    y = root(y)
    if x != y:
        par[x] = y

