def main():
    N = int(input())

    vec = [list(map(int,input().split())) for i in range(N)]

    arg = defaultdict(int)
    zero = 0
    for v in vec:
        if v[0] == 0 and v[1] == 0:
            zero += 1
        else:
            f = Fraction(v[0],v[1])
            arg[f.v()] += 1
            arg[(-f.inv()).v()] += 0

    pair = []
    fd = lambda : False

    checked_list = defaultdict(fd)
    for key in arg:
        if not checked_list[key]:
            inv = (-Fraction(*key).inv()).v()
            pair.append([arg[key],arg[inv]])
            checked_list[inv] = True

    mod = 1000000007

    ans = 1

    for p1,p2 in pair:
        ans *= pow(2,p1,mod) + pow(2,p2,mod) - 1
        ans %= mod

    ans += zero
    ans %= mod

    print((ans+mod-1)%mod)

