dic = OrderedDict(dic)

start = 1
time = 1
st = Stack()
dic[start].flag = 1
dic[start].discover = time
st.add(dic[start])

while not st.isEmpty():
    time += 1
    u = st.top()
    v = u.edge
    if v:
        for i in range(len(v)):
            if dic[v[i]].flag == 0:
                dic[v[i]].flag = 1
                dic[v[i]].discover = time
                if i != len(v)-1:
                    dic[u.id].edge = u.edge[i+1:]
                else:
                    dic[u.id].edge = []
                st.add(dic[v[i]])
                break
        else:
            st.pop()
            dic[u.id].flag = 2
            dic[u.id].finish = time
    else:
        st.pop()    
        dic[u.id].flag = 2
        dic[u.id].finish = time
    if st.isEmpty() and notVisited(dic):
        new = notVisited(dic)
        dic[new].flag = 1
        time += 1
        dic[new].discover = time
        st.add(dic[new])
for i in dic.keys():
