def max_gcd(n):
	g = []
	for p, q in factorization(n):
		g += [p]*q
	g.sort(reverse = True)
	cnt = [0]*len(g)
	cnt_memo = [-1]*len(g)
	for i in range(N):
		a = A[i]
		for j in range(len(g)):
			if a%g[j] == 0:
				cnt[j] += 1
				a //= g[j]
			elif cnt_memo[j] == -1:
				cnt_memo[j] = i

	ans = 1
	flg = True
	for i in range(len(g)):
		if cnt[i] == N:
			ans *= g[i]
		elif cnt[i] == N-1 and flg:
			ans *= g[i]
			flg = False
			tmp = cnt_memo[i]
		elif cnt[i] == N-1 and cnt_memo[i] == tmp:
			ans *= g[i]

	return ans

