def cut(pt, grid, k, h, w):
    pat = []
    for i in range(h-1):
        if pt % 2 == 1:
            pat.append("1")
        else:
            pat.append("0")
        pt //= 2

    # print("pat", pat)
    slice = Counter(pat)["1"]
    pat = pat + ["0"]
    white = [0] * (slice + 1)
    ret = 0
    for i in range(w):
        tw = [0] * (slice + 1)
        dan = 0
        for j in range(h):
            if grid[j][i] == "1":
                tw[dan] += 1
            if pat[j] == "1":
                dan += 1

        if max(tw) > k:
            return INF
        reset = False
        for w1, w2 in zip(white, tw):
            if w1 + w2 > k:
                ret += 1
                reset = True
                break
        if reset:
            white = tw
        else:
            for up in range(slice + 1):
                white[up] += tw[up]

    return ret + slice

