def recursive(i, total, cost, C, A, X):
    if i == len(A):
        return inf
    ncost = recursive(i+1, total, cost, C, A, X)

    ok = True
    for j in (range(len(total))):
        total[j] += A[i][j]
        if (total[j] < X):
            ok = False
    if ok:
        dcost = cost + C[i]
    else:
        dcost = recursive(i+1, total, cost + C[i], C, A, X)
    for j in (range(len(total))):
        total[j] -= A[i][j]

    return (min(ncost, dcost))


