def primeFactorization(n):
    ans = []
    temp = n
    while temp%2 == 0:
        ans.append(2)
        temp //= 2
    for i in range(3, int(n**0.5)+1, 2):
        while temp%i == 0:
            ans.append(i)
            temp //= i
    if temp > 1:
        ans.append(temp)
    return collections.Counter(ans)

def combMod(n, r, p):
    numer = 1
    denom = 1
    for i in range(1, r+1):
        numer = numer * (n-r+i) % p
        denom = denom * i % p
    return numer * pow(denom, p-2, p) % p

def resolve():
    N, M = LI()

    pf = primeFactorization(M)
    # 素因数ごとに、N個のグループにどう振り分けるかを計算する
    ans = 1
    for i in pf.values():
        ans *= combMod(i + N - 1, i, MOD)        
        ans %= MOD

    print(ans)

