def TopologicalSort(graph, in_deg, N):
    sorted_v = []
    q = deque()

    for i in range(N):
        if in_deg[i] == 0:
            q.append(i)

    while q:
        v = q.popleft()
        for n_v in graph[v]:
            in_deg[n_v] -= 1
            if in_deg[n_v] == 0:
                q.append(n_v)

        sorted_v.append(v)

    if len(sorted_v) == N:
        return sorted_v
    else:
        return 0

