    n = _i()
    p = list(filter(lambda x: x != (0, 0), [parse(_s()) for _ in range(n)]))
    u, d = [], []
    for l, r in p:
        u.append((l, r)) if l <= r else d.append((l, r))
    u.sort(key=itemgetter(0))
    d.sort(key=itemgetter(1), reverse=True)
    r = 0
    for ll, rr in u+d:
        if ll > r:
            return 'No'
        r += (rr - ll)

    return 'Yes' if r == 0 else 'No'


