def mod_pow(x , y):
    if y == 0:
        return 1
    if y == 1:
        return x
    r = mod_pow(x , y // 2)
    r2 = (r * r) % MOD
    if y % 2 == 0:
        return r2 % MOD
    else:
        return (r2 * x) % MOD

