def mcomb(n, k, mod):
    if k == 0: return 1     # １分割の場合は１を返すようにしておく
    def mfac(l, r, mod):
        ans = l
        for i in reversed(range(r, l)):
            ans *= i
            ans %= mod
        return ans

    A = mfac(n, n - k + 1, mod)
    B = mfac(k, 1, mod)
    # B = mpow(B,mod-2,mod)
    B = pow(B, mod - 2, mod)
    return A * B % mod

