class dice:
    def __init__(self):
        self.top = 0
        self.right = 0
        self.front = 0
        self.left = 0
        self.back = 0
        self.bottom = 0

    def set_num(self, nums):
        self.top, self.front, self.right, self.left, self.back, self.bottom = nums
